import{_ as o,o as t,c as s,ao as r}from"./chunks/framework.BXus8sEF.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"manual/troubleshooting.md","filePath":"manual/troubleshooting.md","lastUpdated":null}'),a={name:"manual/troubleshooting.md"};function n(i,e,l,d,p,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h1><p><strong>The window does not open, or there is an OpenGL error.</strong> GLMakie needs OpenGL 3.3 or newer. Update the graphics driver. On a remote machine (SSH) you need a display (for example X forwarding or a remote desktop). See the <a href="https://docs.makie.org/stable/explanations/backends/glmakie#Troubleshooting-OpenGL" target="_blank" rel="noreferrer">GLMakie troubleshooting</a>.</p><p><strong>The first start is very slow.</strong> Julia compiles GLMakie on the first start in a Julia session. This takes up to a minute or two. Later starts in the same session are fast. To avoid waiting each time, keep the REPL open and call <code>geometry_picker</code> again.</p><p><strong>The window closes right after it opens (script or <code>julia -e</code>).</strong> The script ended. <code>geometry_picker</code> waits for the window to be closed only when Julia is not interactive, which is the default for scripts. If you set <code>wait = false</code>, set it back to <code>true</code>.</p><p><strong>Nothing happens when I press A and click.</strong></p><ul><li><p>Is the <strong>Picking</strong> toggle on (green)?</p></li><li><p>Is the mouse inside the profile axis?</p></li><li><p>Does the picker window have the keyboard focus? Click once into the window.</p></li><li><p>Is a text field still active (for example the user name field)? Press Enter or click elsewhere first.</p></li></ul><p><strong>I moved a pick by accident.</strong> Switch picking off while you zoom and pan. There is no undo; drag the pick back, or remove it (<strong>D</strong> + click) and add it again.</p><p><strong>Load Picks does nothing.</strong> Look at the REPL. The picks are only loaded if they belong to the loaded profile; the warning says what does not match (type of profile, start and end coordinates, or depth). Use <strong>Load Compare Picks</strong> to see them anyway.</p><p><strong>My user name is not in the saved file.</strong> The user name field only takes the name when you press Enter.</p><p><strong>The colour limits or contour levels do not change.</strong> Press Enter after typing into a text field. Contour levels must be numbers separated by commas, semicolons or spaces; anything else is ignored and the automatic levels are used.</p><p><strong>Load State says the profile file does not exist.</strong> A state stores the full path of the profile file. Move the profile file back, or load the profile with <strong>Load Profile</strong> and the picks from a pick file.</p><p><strong>Where do messages appear?</strong> All messages (what was loaded or saved, warnings and errors) are written to the REPL or terminal from which the picker was started, not into the window.</p>',12)])])}const f=o(a,[["render",n]]);export{g as __pageData,f as default};
